<script setup lang="ts">import {ref,onMounted} from 'vue';import {datasetsStore} from '../stores/datasets';import {get,importCSV} from '../api/datasets';import {canEdit} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import MetricStrip from '../components/common/MetricStrip.vue';const {items,error,reload}=datasetsStore();const selected=ref<any>(null),name=ref('城北补充巡检样本'),filename=ref(''),csv=ref('');const task=useTask();onMounted(async()=>{await reload();if(items.value[0])selected.value=await get(items.value[0].id)});async function selectDataset(id:string){await task.execute(async()=>{selected.value=await get(id)})}async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){filename.value=f.name;csv.value=await f.text()}}function submit(){task.execute(async()=>{await importCSV({name:name.value,filename:filename.value,csv_text:csv.value});await reload();task.message.value='样本已通过校验并保存。';})}</script><template><PageTitle eyebrow="02 / SAMPLE REGISTER" title="先确认样本，再相信模型。" description="检查标签分布、缺失字段与管段唯一性。中位数填补只在训练折内拟合。"/><Notice :error="error||task.error.value" :message="task.message.value"/><div class="split-layout"><section><div class="section-heading"><h2>样本批次</h2><span>{{items.length}} 批</span></div><button class="dataset-row" v-for="d in items" :key="d.id" @click="selectDataset(d.id)"><div><h3>{{d.name}}</h3><small class="mono">{{d.filename}}</small></div><b>{{d.count}} <small>段</small></b></button><template v-if="selected?.rows"><MetricStrip :items="[{label:'记录总数',value:selected.rows.length},{label:'漏损标签',value:selected.rows.filter((r:any)=>r.leak).length},{label:'非漏损标签',value:selected.rows.filter((r:any)=>!r.leak).length}]"/><div class="table-wrap"><table><thead><tr><th>管段</th><th>管材</th><th>管龄</th><th>压力波动</th><th>漏损</th></tr></thead><tbody><tr v-for="r in selected.rows.slice(0,12)" :key="r.pipe_id"><td class="mono">{{r.pipe_id}}</td><td>{{r.material}}</td><td>{{r.age}}</td><td>{{r.pressure_var??'缺失 · 折内填补'}}</td><td>{{r.leak?'是':'否'}}</td></tr></tbody></table></div></template></section><section class="form-panel"><div class="eyebrow">IMPORT / QUALITY GATE</div><h2>补充巡检记录</h2><p>CSV 必含 pipe_id、age、pressure_var、diameter、past_leaks、soil_corrosion、material、leak。管材接受铸铁/钢管/PE/球墨铸铁；正负标签各至少 12 条。</p><form @submit.prevent="submit"><label>批次名称<input v-model="name" required :disabled="!canEdit"></label><label>CSV 文件<input type="file" accept=".csv" @change="file" :disabled="!canEdit"></label><button class="primary" :disabled="!canEdit||!csv||task.busy.value">校验并导入 →</button></form><small v-if="!canEdit">当前为只读角色，可浏览样本；导入需要分析师权限。</small></section></div></template>
